namespace FiveSmartFarmCreators.Ichu.Platform.OperationsMonitoring.Interfaces.Rest.Resources;

/// <summary>
///     Resource representing a stored telemetry reading.
/// </summary>
/// <param name="ReadingId">The reading identifier generated by the device firmware.</param>
/// <param name="DeviceId">The device that captured the reading.</param>
/// <param name="AnimalId">The animal the reading is attributed to, if any.</param>
/// <param name="GatewayId">The Edge Gateway that relayed the reading.</param>
/// <param name="Origin">The component that relayed the reading.</param>
/// <param name="RecordedAt">The instant the device captured the reading.</param>
/// <param name="ReceivedAt">The instant the cloud received the reading.</param>
/// <param name="BodyTemperature">The captured body temperature.</param>
/// <param name="ActivityIndex">The captured activity index.</param>
/// <param name="RuminationMinutes">The captured rumination minutes.</param>
/// <param name="BatteryLevel">The captured battery level.</param>
/// <param name="Position">The captured position.</param>
public record TelemetryReadingResource(
    Guid ReadingId,
    Guid DeviceId,
    Guid? AnimalId,
    Guid GatewayId,
    string Origin,
    DateTimeOffset RecordedAt,
    DateTimeOffset ReceivedAt,
    MeasurementResource BodyTemperature,
    MeasurementResource ActivityIndex,
    MeasurementResource RuminationMinutes,
    MeasurementResource BatteryLevel,
    PositionResource Position);
